import { Chart } from 'moru-ui/chart'
export function WeeklyActivity() {
  return (
    <Chart
      title="Weekly activity"
      xKey="day"
      data={[
        { day: 'Monday', tasks: 24 },
        { day: 'Tuesday', tasks: 36 },
        { day: 'Wednesday', tasks: 28 },
      ]}
      config={{ tasks: { label: 'Completed tasks', color: 'var(--ui-primary)' } }}
      xAxisInterval={0}
      xAxisTickFormatter={(value) => String(value).slice(0, 1)}
    />
  )
}
